package com.mockarena.assessment.infrastructure.question;
import com.fasterxml.jackson.databind.JsonNode; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import java.util.*;
@Component public class RestQuestionEvaluationDataClient implements QuestionEvaluationDataClient { private final RestClient client; public RestQuestionEvaluationDataClient(@Value("${question-service.base-url}")String base){client=RestClient.builder().baseUrl(base).build();} public List<McqEvaluationData> resolve(List<UUID> ids){try{Response r=client.post().uri("/internal/v1/question-versions/evaluation-data").body(new Request(ids)).retrieve().body(Response.class);if(r==null||r.entries()==null||r.entries().size()!=ids.size())throw new QuestionServiceUnavailableException(new IllegalStateException());Set<UUID> seen=new HashSet<>();for(Entry e:r.entries())if(!seen.add(e.questionVersionId())||!ids.contains(e.questionVersionId())||!"MCQ".equals(e.questionTypeCode())||e.correctOptionId()==null)throw new QuestionServiceUnavailableException(new IllegalStateException());return r.entries().stream().map(e->new McqEvaluationData(e.questionVersionId(),e.questionTypeCode(),e.correctOptionId(),e.scoringPolicy())).toList();}catch(RestClientException e){throw new QuestionServiceUnavailableException(e);}} record Request(List<UUID> questionVersionIds){} record Response(List<Entry> entries){} record Entry(UUID questionVersionId,String questionTypeCode,String correctOptionId,JsonNode scoringPolicy){} }
